# The 'default' user source, seeded with the same three demo users as the
# roster demo (idempotent). Bare except on purpose — Jython's 'except
# Exception' does not catch Java exceptions from system.user.
import sys
log = system.util.getLogger('UserDemo')
SRC = 'default'
# DEMO ONLY, NEVER COPY THIS SEEDING: a binding runs for any session that opens the
# view, with no login and no check, so this creates accounts with a known password for anyone.
# A real binding only reads: delete ensure() and the calls to it.
def ensure(username, first, last, contacts):
	try:
		if system.user.getUser(SRC, username) is None:
			u = system.user.getNewUser(SRC, username)
			u.set('firstname', first)
			u.set('lastname', last)
			u.set('password', 'Demo-1234!')
			for t, v in contacts:
				u.addContactInfo(t, v)
			resp = system.user.addUser(SRC, u)
			for err in resp.getErrors():
				log.warn('addUser(' + username + '): ' + unicode(err))
	except:
		log.warn('ensure(' + username + ') failed: ' + unicode(sys.exc_info()[1]))
ensure('jdoe', 'Jane', 'Doe', [('email', 'jane.doe@example.com')])
ensure('mvermeer', 'Mia', 'Vermeer', [('email', 'mia@example.com'), ('sms', '+31600000001')])
ensure('kpatel', 'Kiran', 'Patel', [])
out = []
for u in system.user.getUsers(SRC):
	try:
		ci = []
		for c in u.contactInfo:
			ci.append({'contactType': unicode(c.contactType), 'value': unicode(c.value)})
		def aprop(a, names):
			# The ScheduleAdjustment bean's getter names vary by version.
			for n in names:
				try:
					val = getattr(a, n)
					if val is not None:
						return val
				except:
					pass
			return None
		adjs = []
		for a in u.scheduleAdjustments:
			sd = aprop(a, ['startDate', 'start'])
			ed = aprop(a, ['endDate', 'end'])
			adjs.append({'start': system.date.format(sd, 'yyyy-MM-dd HH:mm') if sd else '', 'end': system.date.format(ed, 'yyyy-MM-dd HH:mm') if ed else '', 'available': bool(aprop(a, ['available']) or False), 'note': unicode(aprop(a, ['note']) or '')})
		out.append({'username': unicode(u.get('username') or ''), 'firstName': unicode(u.get('firstname') or ''), 'lastName': unicode(u.get('lastname') or ''), 'schedule': unicode(u.get('schedule') or ''), 'language': unicode(u.get('language') or ''), 'notes': unicode(u.get('notes') or ''), 'roles': [unicode(r) for r in u.roles], 'contactInfo': ci, 'scheduleAdjustments': adjs})
	except:
		log.warn('map user failed: ' + unicode(sys.exc_info()[1]))
return out

