# Reference persistence: rebuild the PyUser from the flat mirror and write
# it back (addUser when the user is new, editUser otherwise). Roles and contacts are
# rebuilt wholesale; a staged event.password is applied via u.set and NEVER
# logged. Bare except on purpose (Java exceptions).
import sys
s = event.user
username = unicode(s.username)
SRC = 'default'
pw = None
try:
	pw = event.password
except:
	pw = None
# AUTHORIZE FIRST: the flags only hide UI, and a crafted client can send this event
# with any payload. See the adminAuth project library.
# Creating a user, setting a password or changing a user's roles takes the strictest
# check. Whether this creates or changes roles is worked out from the gateway's copy
# of the user, not from event.isNew.
# Any other edit takes only WRITE_ROLES, on any account: a Supervisor can change an
# Administrator's contact details and schedule, and those decide where and when alarm
# notifications reach that person. Decide whether that suits your project.
current = system.user.getUser(SRC, username)
creating = current is None
rolesChanged = set([unicode(r) for r in s.roles]) != set([unicode(r) for r in current.roles] if current else [])
flags = ['editable'] + (['allowCreate'] if creating else []) + (['allowPasswordChange'] if pw else [])
sensitive = creating or bool(pw) or rolesChanged
refused = adminAuth.refusal(self, flags, adminAuth.SECURITY_ROLES if sensitive else adminAuth.WRITE_ROLES)
if refused:
	self.view.custom.lastEvent = 'onUserSave REFUSED: ' + refused
	return
# The create form is asking for a new user: don't overwrite one that has this name.
if bool(event.isNew) and not creating:
	self.view.custom.lastEvent = 'onUserSave REFUSED: a user named "' + username + '" already exists'
	return
# The manager checks names only in the browser, and the gateway stores an empty name, one
# with a line break, and '..'. Checked only for a new name, so existing records stay editable.
if creating:
	bad = adminAuth.nameProblem(username)
	if bad:
		self.view.custom.lastEvent = 'onUserSave REFUSED: ' + bad
		return
try:
	if creating:
		u = system.user.getNewUser(SRC, username)
	else:
		u = current
	u.set('firstname', unicode(s.firstName))
	u.set('lastname', unicode(s.lastName))
	u.set('schedule', unicode(s.schedule))
	u.set('language', unicode(s.language))
	u.set('notes', unicode(s.notes))
	try:
		u.setRoles([unicode(r) for r in s.roles])
	except:
		for r in list(u.roles):
			u.removeRole(unicode(r))
		for r in s.roles:
			u.addRole(unicode(r))
	try:
		u.setContactInfo([])
	except:
		for c in list(u.contactInfo):
			u.removeContactInfo(unicode(c.contactType), unicode(c.value))
	for c in s.contactInfo:
		u.addContactInfo(unicode(c.contactType), unicode(c.value))
	adjs = []
	for a in s.scheduleAdjustments:
		adjs.append(system.user.createScheduleAdjustment(system.date.parse(unicode(a.start), 'yyyy-MM-dd HH:mm'), system.date.parse(unicode(a.end), 'yyyy-MM-dd HH:mm'), bool(a.available), unicode(a.note)))
	try:
		u.setScheduleAdjustments(adjs)
	except:
		for a in list(u.scheduleAdjustments):
			u.removeScheduleAdjustment(a)
		for a in adjs:
			u.addScheduleAdjustment(a)
	if pw:
		u.set('password', unicode(pw))
	if creating:
		resp = system.user.addUser(SRC, u)
	else:
		resp = system.user.editUser(SRC, u)
	errs = [unicode(x) for x in resp.getErrors()]
	if errs:
		self.view.custom.lastEvent = 'onUserSave ERRORS: ' + '; '.join(errs)
	else:
		self.view.custom.lastEvent = 'onUserSave persisted "' + username + '" (isNew=' + unicode(creating) + (', password set' if pw else '') + ')'
except:
	self.view.custom.lastEvent = 'onUserSave FAILED: ' + unicode(sys.exc_info()[1])
self.view.custom.refreshTick = self.view.custom.refreshTick + 1

# AUTHORIZE FIRST: the flags only hide UI, and a crafted client can send this event
# with any payload. See the adminAuth project library.
refused = adminAuth.refusal(self, ['editable', 'allowDelete'], adminAuth.SECURITY_ROLES)
if refused:
	self.view.custom.lastEvent = 'onUserDelete REFUSED: ' + refused
	return
import sys
# The user source matches usernames case-insensitively: removeUser('default', 'ADMIN') removes
# admin. So look the record up, and compare and remove the name it has stored, not this text.
target = system.user.getUser('default', unicode(event.username))
username = unicode(target.get('username')) if target is not None else None
if username is None:
	self.view.custom.lastEvent = 'onUserDelete REFUSED: no user named "' + unicode(event.username) + '"'
elif username == 'admin':
	self.view.custom.lastEvent = 'onUserDelete REFUSED: the demo keeps the admin account'
else:
	try:
		resp = system.user.removeUser('default', username)
		errs = [unicode(x) for x in resp.getErrors()]
		if errs:
			self.view.custom.lastEvent = 'onUserDelete ERRORS: ' + '; '.join(errs)
		else:
			self.view.custom.lastEvent = 'onUserDelete removed "' + username + '"'
	except:
		self.view.custom.lastEvent = 'onUserDelete FAILED: ' + unicode(sys.exc_info()[1])
self.view.custom.refreshTick = self.view.custom.refreshTick + 1

# AUTHORIZE FIRST: the flags only hide UI, and a crafted client can send this event
# with any payload. See the adminAuth project library.
refused = adminAuth.refusal(self, ['editable', 'allowRoleManagement'], adminAuth.SECURITY_ROLES)
if refused:
	self.view.custom.lastEvent = 'onRoleSave REFUSED: ' + refused
	return
# Role-catalog persistence: add or rename (editRole keeps user assignments
# — the source stores role ids — but POLICIES reference roles by name).
import sys
name = unicode(event.name)
old = None
try:
	old = event.oldName
except:
	old = None
if old and unicode(old) != name:
	# Role names match case-insensitively, so only rename a name spelled exactly as the catalog has it.
	if unicode(old) not in [unicode(r) for r in system.user.getRoles('default')]:
		self.view.custom.lastEvent = 'onRoleSave REFUSED: no role named "' + unicode(old) + '"'
		return
	# adminAuth finds its roles by name, so renaming this one would lock out every administrator.
	if unicode(old) == 'Administrator':
		self.view.custom.lastEvent = 'onRoleSave REFUSED: the demo keeps the Administrator role'
		return
# The manager checks names only in the browser, and the gateway stores an empty name, one
# with a line break, and '..'. Checked only for a new name, so existing records stay editable.
if name not in [unicode(r) for r in system.user.getRoles('default')]:
	bad = adminAuth.nameProblem(name)
	if bad:
		self.view.custom.lastEvent = 'onRoleSave REFUSED: ' + bad
		return
try:
	if old and unicode(old) != name:
		resp = system.user.editRole('default', unicode(old), name)
		action = 'renamed "' + unicode(old) + '" -> "' + name + '"'
	else:
		resp = system.user.addRole('default', name)
		action = 'added "' + name + '"'
	errs = [unicode(x) for x in resp.getErrors()]
	if errs:
		self.view.custom.lastEvent = 'onRoleSave ERRORS: ' + '; '.join(errs)
	else:
		self.view.custom.lastEvent = 'onRoleSave ' + action
except:
	self.view.custom.lastEvent = 'onRoleSave FAILED: ' + unicode(sys.exc_info()[1])
self.view.custom.refreshTick = self.view.custom.refreshTick + 1

# AUTHORIZE FIRST: the flags only hide UI, and a crafted client can send this event
# with any payload. See the adminAuth project library.
refused = adminAuth.refusal(self, ['editable', 'allowRoleManagement'], adminAuth.SECURITY_ROLES)
if refused:
	self.view.custom.lastEvent = 'onRoleDelete REFUSED: ' + refused
	return
import sys
name = unicode(event.name)
# Role names match case-insensitively: removeRole('default', 'ADMINISTRATOR') removes it.
# So only act on a name spelled exactly as the catalog has it.
if name not in [unicode(r) for r in system.user.getRoles('default')]:
	self.view.custom.lastEvent = 'onRoleDelete REFUSED: no role named "' + name + '"'
elif name == 'Administrator':
	self.view.custom.lastEvent = 'onRoleDelete REFUSED: the demo keeps the Administrator role'
else:
	try:
		resp = system.user.removeRole('default', name)
		errs = [unicode(x) for x in resp.getErrors()]
		if errs:
			self.view.custom.lastEvent = 'onRoleDelete ERRORS: ' + '; '.join(errs)
		else:
			self.view.custom.lastEvent = 'onRoleDelete removed "' + name + '"'
	except:
		self.view.custom.lastEvent = 'onRoleDelete FAILED: ' + unicode(sys.exc_info()[1])
self.view.custom.refreshTick = self.view.custom.refreshTick + 1
